=== submission_02.ino ===
   1| /*
   2|  * Lab 4: Button toggle
   3|  *
   4|  * Button: D2, internal pull-up, active low
   5|  * LED:    LED_BUILTIN (D13)
   6|  * Output: Serial1, 9600 baud
   7|  *
   8|  * Debounce: the button has to read the same value for DEBOUNCE_TIME ms
   9|  * in a row before we treat it as a real change. Uses millis() so the
  10|  * loop never blocks.
  11|  */
  12| 
  13| #define BUTTON        2
  14| #define DEBOUNCE_TIME 8
  15| 
  16| bool ledState = false;
  17| int  stableLevel = HIGH;
  18| int  prevLevel = HIGH;
  19| unsigned long changeTime = 0;
  20| 
  21| // send the current state out the UART
  22| void sendState() {
  23|   if (ledState) {
  24|     Serial1.print("ON");
  25|   } else {
  26|     Serial1.print("OFF");
  27|   }
  28| }
  29| 
  30| void setup() {
  31|   pinMode(BUTTON, INPUT_PULLUP);
  32|   pinMode(LED_BUILTIN, OUTPUT);
  33|   digitalWrite(LED_BUILTIN, LOW);
  34|   Serial1.begin(9600);
  35| }
  36| 
  37| void loop() {
  38|   int level = digitalRead(BUTTON);
  39| 
  40|   if (level != prevLevel) {
  41|     changeTime = millis();      // bounce or real edge, restart timing
  42|   }
  43|   prevLevel = level;
  44| 
  45|   if ((millis() - changeTime) >= DEBOUNCE_TIME) {
  46|     if (level != stableLevel) {
  47|       stableLevel = level;
  48|       if (stableLevel == LOW) {          // pressed
  49|         ledState = !ledState;
  50|         digitalWrite(LED_BUILTIN, ledState);
  51|         sendState();
  52|       }
  53|     }
  54|   }
  55| }
</student_code>
